from contextlib import contextmanager
from inspect import stack
from logging import Logger
from os.path import basename

from ta_tti_collector.tti_collector import TtiCollector

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST

logger = Logger("LC")


def start_tti_traces_on_enb(tti, **kwargs):
    # type: (TtiCollector, dict) -> List[str]
    """
    Start tti trace on eNB for cells in wanted direction DL, UL or DLUL.

    Example of cells_to_trace:
    r' c2t = {<eNb_id>: {<cell_id>: <direction>}
    r' c2t = {'1': {'1': 'DL', '2': 'UL', '3': 'ULDL'},
    r'        '2': {'1': 'UL', '2': 'UL', '3': 'ULDL'}}

    :param tti: instance of Tti from ta_tti_collector
    :param cells_to_trace: dict with cells to trace
    """
    cells_to_trace = kwargs.pop("cells")
    aliases = []
    logger.info("Inside {} start".format(basename(__file__)))
    for enb, cells in cells_to_trace.items():
        for cell in cells:
            alias_name = "lc_enb{}_cell{}".format(enb, cell)
            tti.register = {alias_name: {"cells": {cell: cells[cell]}, "enb": enb}}
            aliases.append(alias_name)
    for alias in aliases:
        tti.start_collecting(alias=alias)
    logger.info("Inside {} after".format(basename(__file__)))
    return aliases


def start_tti_traces_on_gnb(tti, **kwargs):
    # type: (TtiCollector, dict) -> List[str]
    """
    Start tti trace on gNB for cells in both directions: DL and UL.

    Example of cells_to_trace:
    r' c2t = [<phys_cell1_id>, <phys_cell2_id>, ... , <phys_celln_id>]
    r' c2t = [50, 51]

    :param tti: instance of Tti from ta_tti_collector
    :param gnb: gNB id
    :param cells: list with cells to trace
    """
    cells_to_trace = kwargs.pop("cells")
    gnb_id = kwargs.pop("gnb")
    alias = "tti_lc_gnb_{}".format(gnb_id)
    tti.register = {alias: {"cells": cells_to_trace, "gnb": gnb_id}}
    tti.start_collecting(alias=alias)
    logger.info("Inside {} after".format(basename(__file__)))
    return [alias]


def stop(tti, aliases):
    # type: (TtiCollector, List[str]) -> None
    """
    Stop tti trace and kill hanging processes.

    :param tti: instance of Tti from ta_tti_collector
    :param aliases: list of aliases names to stop
    """
    logger.info("Inside {} before stop".format(basename(__file__)))
    for alias in aliases:
        tti.stop_collecting(alias=alias)
    logger.info("Inside {} after stop".format(basename(__file__)))


def get_start_method(bts_type):
    # type: (str) -> Callable
    """
    Return proper start method for tti trace collection based on BTS type
    :param bts_type: BTS type like gNB or eNB
    """
    bts_type = bts_type.lower()
    if bts_type == "gnb":
        return start_tti_traces_on_gnb
    elif bts_type == "enb":
        return start_tti_traces_on_enb
    else:
        raise ValueError("BTS type {} not supported or recognized".format(bts_type))


@contextmanager
def tti_trace(log_host, log_port, **kwargs):
    # type: (str, int, Dict[str, Union[int, str, dict, list]]) -> Iterator[None]
    """
    Plugin for collecting tti traces from selected cells.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(stack(0)[0][3], SERVER_HOST))
    logger.debug("Received set of params: kwargs = {}".format(kwargs))
    ttitrace = TtiCollector(dest_dir=kwargs.pop("log_dir"), logger=logger)
    aliases = []
    try:
        start = get_start_method(bts_type=kwargs.pop("bts_type"))
        aliases = start(tti=ttitrace, **kwargs)
        yield
    except Exception as e:
        logger.error("TTI trace raised error in running phase. {}".format(e), exc_info=True)
        raise
    finally:
        stop(tti=ttitrace, aliases=aliases)
